/* Original beginner explanations and exercises; linked articles supply the curriculum topics. */
window.ACADEMY_VOLUMES=[{id:'0',title:'Планирование',source:'https://linkmeup.ru/blog/1188/',lessons:window.ACADEMY_COURSE}];
function volume(id,title,source,units){window.ACADEMY_VOLUMES.push({id,title,source,lessons:units.map((u,i)=>({id:`v${id.replace('.','-')}-lesson${i+1}`,title:u[0],time:'6–9 минут',sections:u[1],tasks:u[2],diagram:u[3]}))})}
function task(q,options,answer,why){return{q,options,answer,why}}
volume('13','MPLS Traffic Engineering','https://linkmeup.ru/blog/1232/',[
['Почему кратчайшего пути мало',[
['Трафик идёт неравномерно','Обычная маршрутизация выбирает путь по своей метрике. Самый предпочтительный путь может оказаться перегруженным, пока другая линия простаивает. Traffic Engineering помогает учитывать дополнительные условия и управлять размещением потоков по сети. Это требует знания топологии и ограничений каналов.'],
['Условия для пути','Можно искать путь с достаточной резервируемой полосой, исключать определённые линии или выбирать заданные промежуточные узлы. Условия должны быть совместимы: если подходящего пути нет, туннель нельзя считать успешно созданным. Резервируемая полоса и физическая ёмкость канала — связанные, но разные понятия.'],
['Сначала измерения','Перед переносом потока смотрят загрузку, отказоустойчивость и влияние на другие сервисы. Пустая резервная линия может понадобиться при аварии. Если занять её полностью обычной нагрузкой, после отказа основного канала суммарного ресурса может не хватить.']],[task('Кратчайший по метрике путь всегда самый свободный?',['Да','Нет'],1,'Метрика маршрутизации не обязана отражать текущую загрузку.'),task('Ограничения не допускают ни одного пути. Туннель можно считать рабочим?',['Да','Нет'],1,'Нужен реально рассчитанный и установленный путь.')]],
['RSVP-TE и расчёт',[
['Как узнать свойства линий','TE-расширения протоколов распространяют нужные сведения о ресурсах и атрибутах. На их основе можно выполнить расчёт с ограничениями. Названия конкретных параметров зависят от платформы. Если сведения устарели или неверны, результат тоже может оказаться неподходящим.'],
['Расчёт и сигнализация','CSPF подбирает допустимый путь с учётом ограничений. RSVP-TE может сигнализировать его и резервировать ресурсы на участвующих узлах. Вычислить последовательность узлов и установить состояние на них — разные этапы. Ошибка возможна на каждом.'],
['Не обещаем лишнего','Резервирование не превращает физическую линию в более быструю и не заменяет механизмы очередей и обслуживания трафика. Для нужного качества сервиса приходится согласовывать TE, QoS, политику допуска и реальную нагрузку. Это проект всей сети, а не одна команда.']],[task('CSPF решает какую задачу?',['Расчёт пути с ограничениями','Выдачу адресов DHCP'],0,'Он учитывает ограничения при выборе пути.'),task('Резервирование полосы физически увеличивает скорость кабеля?',['Да','Нет'],1,'Ресурс планируется, но его физическая ёмкость не растёт.')]],
['Защита и приёмка TE',[
['Резерв должен обходить проблему','Защитный путь выбирают так, чтобы он не использовал тот же отказавший ресурс. Разные кабели иногда лежат в одной трубе и могут пострадать одновременно. Независимость путей проверяют физически и логически: разные имена интерфейсов ещё не гарантируют раздельность рисков.'],
['Локальная защита','Fast Reroute может обеспечить локальный обход отказа, пока сеть пересчитывает общий путь. Поддержка, время переключения и охват защиты зависят от реализации. Защита одной линии не обязательно защищает от потери целого узла.'],
['Проверяем сценарии','Нужны проверки отказа линии, отказа узла, возврата основного пути и состояния резервируемых ресурсов. Измеряют потери и задержку во время переключения. Стабильная работа без отказа не доказывает, что резерв действительно спасёт сервис.']],[task('Два кабеля в одной трубе гарантируют независимый резерв?',['Да','Нет'],1,'Одна физическая авария может повредить оба.'),task('Достаточно проверить TE только без отказов?',['Да','Нет'],1,'Защита подтверждается отдельными аварийными сценариями.')]]]);
volume('14','Путь пакета','https://linkmeup.ru/blog/1235/',[
['Control plane и data plane',[
['Кто принимает решения','Control plane обменивается маршрутами и формирует состояние сети. Data plane использует подготовленные таблицы для пересылки пользовательских пакетов. Это помогает отличить проблему протокола маршрутизации от неисправности самой пересылки. Обе части должны согласованно работать.'],
['RIB и FIB','RIB содержит маршрутную информацию и результат выбора маршрутов. FIB предназначена для выполнения пересылки. Наличие записи в протокольной базе ещё не означает, что она стала активным маршрутом и попала в нужную таблицу оборудования. При диагностике важно знать, какую таблицу вы смотрите.'],
['Процессор не делает всё','Во многих устройствах обычная пересылка выполняется специализированной аппаратурой. Некоторые пакеты направляются центральному процессору, например для управления или особой обработки. Высокая скорость портов не означает, что CPU сможет обработать такой же объём исключительного трафика.']],[task('Что обычно пересылает пользовательские пакеты по готовым таблицам?',['Data plane','Только протокол BGP'],0,'Control plane готовит состояние, data plane выполняет пересылку.'),task('Любая запись в базе BGP обязательно активна в FIB?',['Да','Нет'],1,'Маршрут проходит выбор и установку.')]],
['Что происходит на каждом шаге',[
['Входной кадр','Интерфейс принимает сигнал и проверяет кадр. Затем устройство определяет контекст, например VLAN или VRF, и применяет соответствующие правила. Конкретный порядок операций зависит от архитектуры. Поэтому универсальная картинка помогает мыслить, но не заменяет документацию платформы.'],
['Маршрутизатор меняет оболочку','При обычной IP-маршрутизации входной L2-заголовок не путешествует неизменным через всю сеть. Для следующего участка формируется новый кадр. IPv4 TTL уменьшается; при отсутствии NAT адреса IP обычно остаются исходными. Изменение MAC между участками нормально.'],
['Выход','После выбора направления пакет попадает на выходной интерфейс и может ожидать обслуживания в очереди. На каждом этапе возможен отдельный отказ: фильтр, отсутствие маршрута, неразрешённый сосед, переполнение очереди. По одному внешнему симптому нельзя сразу назвать виновный этап.']],[task('MAC назначения обязан быть одинаковым через все роутеры?',['Да','Нет'],1,'Каждый Ethernet-участок имеет свою L2-оболочку.'),task('Что обычно происходит с TTL при маршрутизации?',['Уменьшается','Становится бесконечным'],0,'TTL ограничивает время жизни пакета в маршрутизируемой сети.')]],
['Диагностика по доказательствам',[
['Ищем точку исчезновения','Сравнивают счётчики на соседних интерфейсах и захваты на разрешённых точках. Если пакет пришёл, но не вышел, проверяют контекст, фильтры, таблицы пересылки и выходные очереди. Служебный ping самого роутера может идти иным путём обработки, чем транзитный трафик.'],
['Проверяем оба направления','Сервису часто нужен не только запрос, но и ответ. У асимметричного пути могут быть разные фильтры и состояния firewall. Неуспех одной проверки не следует автоматически переносить на все протоколы и размеры пакетов. Формулируйте точный тест: источник, получатель, протокол и размер.'],
['Меняем одну причину','Сохраните наблюдения до изменения, затем повторите тот же тест после. Если одновременно заменить кабель, правила и адреса, станет трудно понять причину. Хорошая диагностика заканчивается не зелёной иконкой, а повторяемой проверкой нужного пользовательского действия.']],[task('Ping самого роутера полностью проверяет транзитную обработку?',['Да','Нет'],1,'Локальный и транзитный трафик могут обрабатываться по-разному.'),task('Для сравнения до и после нужен какой тест?',['Один и тот же определённый сценарий','Каждый раз случайная проверка'],0,'Повторяемость позволяет оценить влияние исправления.')]]]);
volume('15','QoS','https://linkmeup.ru/blog/1244/',[
['Что чувствует приложение',[
['Скорость — не единственный показатель','Для разговора важны задержка, её колебания и потери пакетов. Большая средняя скорость не спасает от длинных пауз в очереди. При скачивании файла приложение часто может подождать повторной передачи, а слишком поздний кусочек живого разговора уже мало полезен.'],
['Очередь у узкого места','Когда пакеты приходят быстрее, чем выход может передать, они ожидают в буфере. Слишком долгая очередь увеличивает задержку, а заполненный буфер приводит к потерям. Добавление памяти не увеличивает скорость выхода: иногда оно только позволяет дольше ждать.'],
['Задача QoS','QoS помогает распределять ограниченные ресурсы по правилам. Надо решить, какие классы обслужить раньше, кому выделить долю и что делать при перегрузке. Такие решения имеют цену: приоритет одного класса влияет на обслуживание остальных.']],[task('QoS превращает 100 Мбит/с в физические 1 Гбит/с?',['Да','Нет'],1,'QoS распределяет имеющийся ресурс.'),task('Для голоса важны только мегабиты?',['Да','Нет, ещё задержка, джиттер и потери'],1,'Своевременная доставка влияет на качество разговора.')]],
['Классификация и очереди',[
['Узнаём тип трафика','Классификация относит пакеты к классам по доступным признакам. Маркировка записывает обозначение класса, например DSCP в IP-заголовке. Соседнее устройство может учитывать метку, менять её или игнорировать: одинаковое обслуживание по всей сети требует согласованной политики.'],
['Кому доверять','Если любой клиент может поставить высший приоритет своим загрузкам, политика теряет смысл. Границу доверия выбирают осознанно. Важен не только красивый номер DSCP, но и реальное соответствие очереди, ограничению и способу обслуживания на каждом узком месте.'],
['Приоритет с ограничением','Строгий приоритет может уменьшить ожидание чувствительного трафика, но без ограничений способен вытеснить остальные классы. Поэтому проектируют доли, лимиты и ожидаемую нагрузку. Маркировка сама по себе не меняет порядок очередей, если оборудование не использует её в политике.']],[task('Поставили DSCP, но политики очередей нет. Приоритет гарантирован?',['Да','Нет'],1,'Метка должна использоваться механизмом обслуживания.'),task('Всем клиентским меткам высшего приоритета нужно слепо доверять?',['Да','Нет'],1,'Граница доверия защищает политику от произвольных меток.')]],
['Shaping, policing и проверка',[
['Сгладить или отбросить','Shaping задерживает часть трафика, сглаживая отправку до заданного профиля. Policing обычно отбрасывает или перемаркирует превышение по правилам. Это разные действия: одно может добавить ожидание, другое — потери. Внутренний буфер shaping тоже конечен.'],
['Короткие всплески','Средняя скорость может быть небольшой, но пакеты приходят коротким плотным всплеском. В этот момент выходная очередь переполняется. Поэтому средние графики не всегда показывают причину потерь. Параметры burst и механизм ограничения выбирают с учётом такого поведения.'],
['Тест под нагрузкой','Проверяют голос или другой важный сервис одновременно с нагрузкой на узкое место. Смотрят задержку, потери, загрузку и счётчики классов. Проверка в пустой сети не демонстрирует работу очередей при перегрузке. После настройки убеждаются, что остальные сервисы тоже остаются работоспособны.']],[task('Какой механизм обычно задерживает пакеты для сглаживания скорости?',['Shaping','Policing'],0,'Shaping использует ожидание, policing применяет действие к превышению.'),task('Для проверки QoS нужна нагрузка на узкое место?',['Да','Нет'],0,'Без конкуренции за ресурс поведение очередей почти не проявляется.')]]]);
volume('8','BGP и IP SLA','https://linkmeup.ru/blog/1198/',[
['Автономные системы и соседи',[
['Сеть под общим управлением','Автономная система, AS, — домен маршрутизации с собственным управлением и политикой. BGP помогает обмениваться достижимостью сетей между такими доменами и внутри них. Номер AS обозначает участника маршрутизации, но не является IP-адресом конкретного роутера.'],
['Сначала соединение','Соседи BGP должны иметь сетевую достижимость и согласованные параметры. Сессия использует TCP. Установленная сессия означает возможность обмена, но не подтверждает, что нужный префикс получен, принят политикой и выбран для пересылки. Это отдельные проверки.'],
['Не только скорость','BGP выбирает маршруты с учётом атрибутов и политики. Он не измеряет автоматически реальную задержку до каждого сайта, чтобы всегда выбрать самый быстрый канал. Решение зависит от того, какие пути приняты и какие предпочтения настроил оператор.']],[task('Номер AS — это адрес отдельного интерфейса?',['Да','Нет'],1,'ASN идентифицирует автономную систему, а интерфейсу нужен IP-адрес.'),task('Сессия BGP установлена. Нужный маршрут обязательно уже выбран?',['Да','Нет'],1,'Его могли не объявить, отфильтровать или не выбрать.')]],
['Политики и два провайдера',[
['Управляем исходящим трафиком','Сеть может получать один префикс от разных провайдеров. Local Preference часто используют для внутреннего предпочтения выхода: больший Local Preference обычно предпочтительнее при прочих условиях алгоритма. Влияние на исходящий и входящий трафик — разные задачи.'],
['Фильтры на границе','Принимать и объявлять следует только ожидаемые сети. Ошибка объявления может отправить чужой трафик по неправильному пути. Prefix-list и другие механизмы помогают ограничить набор маршрутов. Получение полной интернет-таблицы требует подходящих ресурсов; небольшой сети иногда достаточно default route.'],
['IBGP внутри AS','IBGP распространяет BGP-маршруты внутри одной AS. Для масштабирования используют осознанную топологию сессий, например route reflector. Обычный IBGP-сосед не пересылает маршрут от одного IBGP-соседа другому по умолчанию. Также проверяют достижимость next hop.']],[task('Что обычно предпочитается по Local Preference?',['Большее значение','Меньшее значение'],0,'Local Preference задаёт предпочтение пути внутри AS.'),task('Фильтровать собственные анонсы нужно?',['Да','Нет'],0,'Нужно исключить случайную публикацию лишних префиксов.')]],
['IP SLA: проверяем дальше порта',[
['Линия поднята, сервис упал','Интерфейс может оставаться up, даже когда за провайдером пропала доступность. Активная проверка отправляет тестовый трафик к выбранной цели. Проверка одного адреса показывает доступность именно этой цели по выбранному способу, а не здоровье всего интернета.'],
['Связываем измерение с действием','IP SLA на поддерживаемых платформах выполняет измерения, а tracking и маршрутизация могут использовать их результат. Задают частоту, таймаут и условия переключения. Иначе кратковременная потеря одного ответа может вызвать лишнее переключение туда и обратно.'],
['Контролируем путь самой проверки','Если тест случайно уйдёт через резерв, он может объявить основной путь исправным. Поэтому источник и маршрут проверки должны соответствовать проверяемому каналу. После внедрения отдельно проверяют отказ, восстановление и сохранение административного доступа.']],[task('Порт up гарантирует доступность сервера за провайдером?',['Да','Нет'],1,'Состояние локальной линии не описывает весь путь.'),task('Проверка основного канала ушла через резерв. Результат надёжен?',['Да','Нет'],1,'Проверяется уже другой путь.')]]]);
volume('9','Мультикаст','https://linkmeup.ru/blog/1205/',[
['Один поток для группы',[
['Три способа доставки','Unicast адресован одному получателю. Broadcast распространяется по локальному широковещательному сегменту. Multicast адресован группе заинтересованных получателей. Это удобно, когда один и тот же поток одновременно нужен многим, например управляемому телевидению в сети оператора.'],
['Где появляются копии','Источник может отправлять один поток, а сеть создаёт копии там, где расходятся пути к получателям. Экономия зависит от общей части этих путей. Само приложение и сеть должны поддерживать такой режим: обычная передача видео через интернет автоматически мультикастом не становится.'],
['Адрес группы','IPv4 multicast использует специальный диапазон групповых адресов. Адрес группы не является адресом одного конкретного телевизора. Источник при этом имеет собственный обычный адрес. Политика сети определяет, где разрешено принимать и распространять группы.']],[task('Multicast отправляет данные кому?',['Группе заинтересованных получателей','Всегда всем компьютерам интернета'],0,'Групповая доставка отличается от broadcast.'),task('Копии потока могут создаваться внутри сети?',['Да','Нет'],0,'Разветвление позволяет не отправлять отдельную копию с источника каждому.')]],
['IGMP и Snooping',[
['Получатель сообщает интерес','IGMP используется между IPv4-получателями и маршрутизаторами на локальном участке. Клиент сообщает об участии в группе. Отсутствие ожидаемого членства может объяснить, почему поток не направляется к нему. Для IPv6 соответствующую роль выполняет MLD.'],
['Коммутатор тоже наблюдает','IGMP Snooping позволяет коммутатору учитывать сообщения членства и ограничивать распространение потока нужными портами. Это не протокол межсетевой multicast-маршрутизации. Нужны корректное обнаружение направления к маршрутизатору и работа querier в соответствующем сценарии.'],
['Проверяем таймеры','Подписки обновляются и могут истекать. Если видео сначала работает, а потом пропадает, стоит проверить запросы членства и таблицу snooping. Просто постоянно заливать поток во все порты может скрыть причину и перегрузить устройства, которым видео не требуется.']],[task('IGMP Snooping заменяет маршрутизацию между подсетями?',['Да','Нет'],1,'Snooping управляет распространением на L2, а межсетевой путь решается отдельно.'),task('Получатели используют IGMP для чего?',['Сообщать интерес к группе','Выдавать DHCP-адреса'],0,'IGMP обслуживает членство в IPv4 multicast-группах.')]],
['PIM и путь от источника',[
['Соединяем разные участки','Для доставки групп между сетями нужны multicast-маршруты. PIM использует сведения базовой маршрутизации, чтобы строить деревья доставки. Устройство учитывает, с какого направления ожидает источник: проверка RPF помогает не принимать поток с неправильного пути.'],
['RP и SSM','В PIM Sparse Mode точка RP может помогать свести источники и получателей. В SSM получатель указывает конкретный источник и группу; роль общей точки встречи для этого сценария не требуется. Эти режимы нельзя бездумно считать одинаковой настройкой с разными названиями.'],
['Диагностика по цепочке','Проверьте источник, членство клиента, PIM-соседей, состояние дерева и RPF. Unicast-ping от телевизора к серверу подтверждает лишь часть условий: групповая доставка использует свои таблицы. Сравнение счётчиков на входе и выходе помогает найти участок потери.']],[task('Unicast ping работает. Multicast точно настроен?',['Да','Нет'],1,'Нужны членство, дерево доставки и корректная multicast-пересылка.'),task('RPF проверяет какое направление?',['Ожидаемое направление к источнику','Цвет телевизора'],0,'Это защита корректного построения пути потока.')]]]);
volume('10','Базовый MPLS','https://linkmeup.ru/blog/1207/',[
['Пакет получает метку',[
['Короткое указание следующего действия','MPLS использует метки для пересылки по подготовленному пути. Входное устройство может добавить метку, промежуточное — заменить её, а выходное — снять. Метка имеет смысл в контексте конкретного участка и таблицы, а не как глобальный почтовый адрес.'],
['Три операции','Push добавляет метку, Swap заменяет верхнюю, Pop снимает её. В пакете может быть стек из нескольких меток: внешняя помогает транспорту, внутренняя может обозначать сервис. Не нужно считать, что номер метки обязан оставаться одним и тем же на всех маршрутизаторах.'],
['Зачем это нужно','MPLS служит основой транспортных и VPN-сервисов. Само наличие метки не шифрует полезную нагрузку и не гарантирует ускорение любого маршрутизатора. Важно понимать сервис и таблицы пересылки, а не только выучить расшифровку названия.']],[task('Замена верхней метки называется как?',['Swap','ARP'],0,'Swap заменяет метку согласно таблице пересылки.'),task('Метка обязана быть одинаковой на всём пути?',['Да','Нет'],1,'Метки назначаются и интерпретируются в соответствующем контексте.')]],
['LDP и транспортный путь',[
['Сначала IP-связность','В типичной сети с LDP базовый IGP обеспечивает достижимость транспортных узлов. LDP распространяет привязки меток к классам пересылки. Неисправная базовая маршрутизация может нарушить MPLS, даже если часть соседств LDP видна.'],
['Маршруты и метки связаны','Для передачи нужен подходящий следующий узел и метка, которую он ожидает. Проверяют не только таблицу IP-маршрутов, но и таблицу пересылки меток. Присутствие соседа по протоколу ещё не гарантирует готовый путь для выбранного назначения.'],
['Снятие перед последним узлом','В некоторых схемах предпоследний маршрутизатор снимает транспортную метку: это PHP. Тогда на последнем участке стек может выглядеть иначе. Такое изменение само по себе не является потерей сервиса. Надо понимать ожидаемое действие каждого узла.']],[task('Для LDP-транспорта полезно сначала проверить IGP?',['Да','Нет'],0,'Транспорт зависит от базовой достижимости и следующего узла.'),task('Снятая предпоследним узлом метка всегда означает ошибку?',['Да','Нет'],1,'PHP может быть нормальным поведением.')]],
['Практикум: читаем стек',[
['Два уровня смысла','Представьте пакет с двумя метками. Верхняя ведёт к выходному узлу сети оператора. Следующая позволяет выходному узлу определить нужный сервис. Пока пакет идёт через ядро, ядру не обязательно знать все внутренние адреса клиента.'],
['Размер пакета','Стек меток добавляет байты. Сеть должна вмещать получившийся пакет на каждом нужном участке. Если обычный IP-пакет проходит, а VPN с метками теряет большие пакеты, проверка MTU становится важной частью диагностики.'],
['Ищем разрыв','Сравните ожидаемый next hop, входную и выходную метки и состояние интерфейса. Сервисная неисправность может существовать при рабочем транспорте, и наоборот. Следующие тома объяснят, как поверх этого транспорта разделяют клиентские L3- и L2-сети.']],[task('Внешняя метка обычно решает какую задачу в двухметочном VPN-примере?',['Доставку к выходному узлу','Назначение пароля клиенту'],0,'Внутренняя метка несёт сервисный смысл.'),task('Добавление меток влияет на MTU?',['Да','Нет'],0,'Заголовки занимают дополнительное место.')]]]);
volume('11','MPLS L3VPN','https://linkmeup.ru/blog/1212/',[
['Разные клиенты, отдельные таблицы',[
['Адреса могут совпадать','Две компании могут использовать одинаковую частную подсеть. Оператору нужно обслуживать их раздельно. VRF создаёт отдельный контекст маршрутизации: адрес в одной VRF не становится автоматически маршрутом другой. На границе важно назначить интерфейс правильному клиенту.'],
['CE, PE и P','CE находится со стороны клиента. PE — граничное устройство оператора, которое обслуживает VPN-контекст. P — транспортный узел ядра. В типичной архитектуре ядро переносит MPLS-трафик и не хранит все маршруты каждой клиентской VRF.'],
['Изоляция не равна шифрованию','L3VPN разделяет маршрутизацию клиентов. Требования к криптографической защите рассматривают отдельно: слово VPN не обещает шифрования. Политика оператора должна исключать случайный обмен между контекстами и разрешать только нужные общие сервисы.']],[task('Для двух клиентов с одинаковыми частными адресами полезно что?',['Отдельные VRF','Смешать все маршруты'],0,'Контекст позволяет различать одинаковые адресные пространства.'),task('P-узел обязательно хранит все клиентские подсети?',['Да','Нет'],1,'В типичной MPLS L3VPN ядро использует транспортные метки.')]],
['RD, RT и MP-BGP',[
['Как различить одинаковые префиксы','Route Distinguisher, RD, делает клиентский префикс уникальным в VPN-адресном семействе. Он не является сам по себе правилом разрешения обмена. Не следует пытаться определить политику импорта только по совпадению RD.'],
['Кому импортировать маршрут','Route Target, RT, используется в политике экспорта и импорта VPN-маршрутов. MP-BGP распространяет маршруты и связанные атрибуты. Если нужный маршрут не появился в VRF, проверяют экспорт на исходной стороне и импорт на принимающей.'],
['Транспорт тоже должен работать','Даже правильно полученный VPN-маршрут требует достижимого PE и рабочего транспорта. Для трафика должны согласоваться сервисная метка, next hop и MPLS-путь. Отдельно проверяют обмен маршрутов между CE и PE.']],[task('Что обычно управляет импортом VPN-маршрутов?',['RT','Только RD'],0,'RT связан с политикой включения маршрутов в VRF.'),task('Маршрут есть в MP-BGP, но отсутствует в VRF. Что проверить?',['Политику импорта RT','Только питание ноутбука'],0,'Маршрут должен быть принят нужным контекстом.')]],
['Общие сервисы и интернет',[
['Открываем только нужное','Иногда нескольким клиентским сегментам нужен общий сервис. Такой обмен проектируют явно: какие маршруты импортируются, где применяются фильтры и как возвращается ответ. Широкий импорт всех клиентских маршрутов может разрушить задуманную изоляцию.'],
['Выход наружу','Интернет-доступ из VRF требует выбранной схемы выхода, маршрута по умолчанию и обратной достижимости. NAT может потребоваться для частных адресов, но это не обязательное свойство любого L3VPN. Нужно учитывать адреса клиента и условия подключения.'],
['Приёмка','Проверьте связь между нужными филиалами, недоступность чужого контекста, общий сервис и обратный путь. Тесты разрешённого и запрещённого трафика одинаково важны. Успешный ping между двумя PE не проверяет доступность клиентского сервера.']],[task('Общий сервис требует импортировать вообще все клиентские маршруты?',['Да','Нет'],1,'Лучше явно ограничить необходимый обмен.'),task('Как проверить изоляцию?',['Проверить и разрешённые, и запрещённые направления','Только ping ядра'],0,'Изоляция — самостоятельное требование к сервису.')]]]);
volume('12','MPLS L2VPN','https://linkmeup.ru/blog/1219/',[
['Ethernet через сеть оператора',[
['Клиенту нужен L2','Иногда клиент хочет соединить площадки так, будто между ними есть Ethernet-сегмент. L2VPN переносит кадры, а IP-маршрутизацию клиент может организовать самостоятельно. Это отличается от L3VPN, где оператор участвует в обмене IP-маршрутами клиента.'],
['Точка-точка','VPWS связывает две точки услуги. Pseudowire можно представить как логическое соединение поверх транспорта. Для работы нужны корректные параметры подключения клиента, идентификаторы сервиса и достижимость между граничными устройствами. Один только рабочий MPLS-транспорт не создаёт сервис автоматически.'],
['Граница ответственности','Стороны должны согласовать MTU, обработку VLAN и ожидаемый тип сервиса. Прозрачность услуги не означает, что любое служебное сообщение обязано проходить без изменений. Условия определяются конкретной технологией и конфигурацией.']],[task('L2VPN прежде всего переносит что?',['Ethernet-кадры клиента','Только записи DNS'],0,'Клиент может сам строить IP-сеть поверх услуги.'),task('VPWS в базовом виде соединяет сколько точек?',['Две','Любое число без дополнительных механизмов'],0,'Это сервис точка-точка.')]],
['VPLS: несколько площадок',[
['Общий виртуальный коммутатор','VPLS даёт многоточечную L2-связь. Граничные узлы изучают клиентские MAC и направляют кадры к нужной стороне. Для неизвестного назначения и широковещания требуется распространение по участвующим точкам, поэтому объём такого трафика имеет значение.'],
['Петли и масштаб','Общий Ethernet-домен через несколько площадок несёт риски петель и широковещательных штормов. Используются механизмы предотвращения повторной пересылки и согласованная схема подключений. Нельзя считать, что расстояние между городами само защищает от L2-петли.'],
['Проверяем MAC','Сравните изученные адреса, привязку к подключению клиента и состояние pseudowire. Если MAC постоянно переезжает между сторонами, причина может быть в петле или двойном несогласованном подключении. Разбирайте физическую схему вместе с логической услугой.']],[task('В VPLS появляется задача изучения MAC?',['Да','Нет'],0,'Многоточечный L2-сервис должен знать направления к получателям.'),task('Логический Ethernet между городами может иметь петлю?',['Да','Нет'],0,'Дистанция не отменяет свойства L2-топологии.')]],
['EVPN и резервное подключение',[
['Маршруты сообщают о MAC','EVPN использует BGP для распространения информации о достижимости Ethernet и связанных данных. Это другой подход к control plane по сравнению с одним лишь изучением адресов из пользовательских кадров. Транспортом может быть MPLS или VXLAN в соответствующей архитектуре.'],
['Два подключения к клиенту','При multihoming клиентское устройство подключается к нескольким граничным узлам. Идентификация общего сегмента и согласованное поведение помогают сохранить резерв и избежать лишних копий. Режимы single-active и all-active имеют разную семантику.'],
['Что проверять при отказе','Проверьте, как меняется путь к MAC после потери одной связи, нет ли дубликатов и петель, сколько длится восстановление. Отдельно проверяют массовую рассылку и обычный unicast. Сам факт двух физических кабелей не подтверждает корректное резервирование.']],[task('EVPN распространяет информацию с помощью чего?',['BGP','Только DHCP'],0,'BGP выступает протоколом control plane EVPN.'),task('Два кабеля гарантируют готовый multihoming без настройки?',['Да','Нет'],1,'Нужны согласованные роли, идентификаторы и режим сервиса.')]]]);
volume('4','L2 и STP','https://linkmeup.ru/blog/1192/',[
['Почему возникает петля',[
['Лишний путь может мешать','Две линии между коммутаторами кажутся хорошим резервом. Но если обе передают один VLAN независимо, широковещательный кадр может начать ходить по кругу и размножаться. У обычного Ethernet-кадра нет IP-подобного TTL, который остановит такое движение. Сеть перегружается даже без полезных файлов.'],
['Задача STP','Spanning Tree Protocol выбирает логическую топологию без циклов. Часть избыточных путей не передаёт пользовательский трафик, но может стать полезной после отказа. Физический кабель при этом остаётся на месте. Блокировка резервного пути — ожидаемая работа защиты, а не обязательно неисправность порта.'],
['Что наблюдать','При петле возможны рост broadcast, скачки загрузки и перемещение одного MAC между портами. Проверяют схему, роли STP и журналы. Отключение STP ради зелёного статуса всех линий может ухудшить ситуацию. Резервирование проектируют заранее и проверяют в учебной среде.']],[task('Два независимых кабеля в одном VLAN могут создать петлю?',['Да','Нет'],0,'Без механизма исключения циклов кадры могут циркулировать.'),task('Резервный порт STP не передаёт данные. Это всегда поломка?',['Да','Нет'],1,'Порт может намеренно исключать лишний путь.')]],
['Корень и резервный путь',[
['Выбираем опорное устройство','STP выбирает корневой коммутатор по Bridge ID: учитываются приоритет и идентификатор устройства. На остальных коммутаторах определяется путь к корню. Корень лучше назначать осознанно, чтобы случайный маленький коммутатор не стал центром логической топологии.'],
['Стоимость имеет значение','STP сравнивает стоимость путей и использует дополнительные правила при равенстве. Это не просто подсчёт числа проводов. После отказа протокол перестраивает дерево. Скорость восстановления зависит от варианта STP, топологии и настроек; нельзя обещать одинаковое время для любой сети.'],
['Разные варианты','RSTP ускоряет переходы в типичных условиях, MSTP позволяет связывать группы VLAN с экземплярами дерева. На пользовательских портах применяют подходящие защитные механизмы, например BPDU Guard в согласованной конфигурации. Порт к другому коммутатору нельзя бездумно считать портом обычного компьютера.']],[task('Корневой коммутатор лучше выбирать как?',['Осознанно по проекту','Случайно при каждом монтаже'],0,'Так путь трафика и поведение резерва предсказуемее.'),task('Любой STP всегда восстанавливает связь за одно время?',['Да','Нет'],1,'Время зависит от протокола и условий сети.')]],
['LAG и защита доступа',[
['Несколько линий как одна','LAG объединяет совместимые линии в логическое соединение. LACP помогает согласовать участников. Обычно потоки распределяются по хешу, поэтому один файл не обязан использовать сумму скоростей всех кабелей. Концы агрегата должны быть согласованы по параметрам.'],
['Поддельный DHCP','Посторонний DHCP-сервер может выдать клиентам неверный шлюз. DHCP Snooping помогает различать доверенные направления и сообщения клиентов, а связанные механизмы могут проверять привязки адресов. Неправильно выбранный trusted-порт тоже опасен: защиту нужно применять по схеме.'],
['Практическая проверка','Сверьте состав агрегата на обоих концах, состояние LACP и доступные VLAN. Затем проверьте отказ одной линии. Для DHCP убедитесь, что ответы настоящего сервера проходят, а ответы со случайного пользовательского порта блокируются. Начинайте с отдельных проверяемых изменений.']],[task('Две линии по 1 Гбит/с в LAG гарантируют одному потоку 2 Гбит/с?',['Да','Нет'],1,'Обычно один поток выбирает одну линию по хешу.'),task('Доверять DHCP-ответам стоит с какого направления?',['С любого пользовательского порта','С предусмотренного пути к серверу'],1,'Доверенные направления определяют по реальной схеме.')]]]);
volume('5','NAT и ACL','https://linkmeup.ru/blog/1193/',[
['Правила доступа ACL',[
['Пакет проходит список','ACL — список правил разрешения и запрета. В типичном списке правила проверяются сверху вниз до первого совпадения. Поэтому общий запрет перед узким разрешением может сделать разрешение бесполезным. На платформе уточняют действие для трафика, который не совпал ни с одной строкой.'],
['Что именно проверяем','Правило может учитывать адреса источника и получателя, протокол и порты. Например: гостям разрешить DNS к определённому серверу и доступ наружу, а рабочий сервер закрыть. Направление in/out выбирается относительно конкретного интерфейса устройства, а не относительно всей компании.'],
['Не потерять управление','Перед применением продумайте, как проходит ваш административный сеанс. Проверьте порядок строк и отдельные разрешения для управления. Простая ACL не равна межсетевому экрану с отслеживанием состояния соединений. Нужно понимать, что происходит с ответным трафиком.']],[task('Сначала стоит deny all, ниже разрешение к серверу. Разрешение сработает?',['Да','Нет при проверке до первого совпадения'],1,'Пакет совпадёт с общим запретом раньше.'),task('Направление in относится к чему?',['Входу на выбранный интерфейс','Любому интернет-трафику вообще'],0,'Нужно мысленно проследить путь через конкретный порт.')]],
['Что меняет NAT',[
['Адрес на границе','NAT изменяет адресную информацию при прохождении границы сети. При выходе из домашней сети частный адрес компьютера может заменяться внешним адресом роутера. Таблица трансляций помогает сопоставить ответ с внутренним соединением. Роутеру всё равно нужны корректные маршруты.'],
['Много клиентов и один адрес','PAT, или overload, различает соединения с помощью портов и других параметров. Благодаря этому несколько клиентов используют один внешний IPv4-адрес. Публикация внутреннего сервиса через проброс порта — отдельная задача: нужно выбрать назначение и ограничить доступ.'],
['Не путать с защитой','NAT не шифрует данные и не является полноценной политикой безопасности. Отсутствие входящего сопоставления часто мешает нежелательным подключениям, но разрешения должен контролировать межсетевой экран. Некоторые приложения страдают от изменения адресов и нуждаются в дополнительных механизмах.']],[task('NAT автоматически шифрует содержимое пакета?',['Да','Нет'],1,'Преобразование адреса не является шифрованием.'),task('Зачем PAT использует порты?',['Чтобы различать соединения клиентов','Чтобы увеличить длину кабеля'],0,'Соединения разделяются даже при одном внешнем адресе.')]],
['Практикум: гости и сервер',[
['Разделяем задачи','Гости должны открывать сайты, но не подключаться к рабочему серверу. VLAN отделяет сегмент, маршрутизация задаёт пути, ACL или firewall определяет разрешения, а NAT при необходимости переводит частные адреса для выхода наружу. Ни один пункт не заменяет все остальные.'],
['Проверяем ожидаемое','Составьте таблицу: гостевой телефон → DNS — разрешено; телефон → интернет — разрешено; телефон → рабочий сервер — запрещено. Проверяйте каждую строку отдельно. Успешный выход на один сайт не доказывает, что сервер закрыт или что все сервисы разрешены.'],
['Смотрите счётчики','Счётчики правил и таблица NAT помогают увидеть, куда попал трафик. При ошибке уточните адреса до и после трансляции: порядок NAT и фильтрации зависит от платформы и направления. Не угадывайте, какие адреса видит конкретная стадия обработки.']],[task('Гости выходят в интернет. Значит ли это, что рабочий сервер закрыт?',['Да','Нет, запрет надо проверить отдельно'],1,'Работа разрешённого пути не доказывает блокировку запрещённого.'),task('ACL не получает совпадений. Что проверить?',['Интерфейс, направление и адреса на этой стадии','Только название правила'],0,'Правило должно видеть реальные поля проходящего пакета.')]]]);
volume('6','Динамическая маршрутизация','https://linkmeup.ru/blog/1195/',[
['Зачем маршрутизаторам общаться',[
['Сеть растёт','Когда площадок много, ручное обновление маршрутов становится трудным. Протокол динамической маршрутизации позволяет устройствам обмениваться сведениями и выбирать пути по заданным правилам. Он работает внутри ограниченной области доверия и не угадывает желания владельца без настройки.'],
['Соседство и сходимость','Сначала устройства должны установить требуемое соседство или обмен. Затем распространяется информация и рассчитываются пути. После отказа требуется время, чтобы все участники согласовали новое состояние. Этот процесс называют сходимостью. Даже динамическая сеть может временно терять пакеты.'],
['Разные источники маршрутов','На устройстве могут одновременно существовать подключённые сети, статические записи и протоколы. Сначала важно понять, какие маршруты вообще установлены, а затем применять самое длинное совпадение к пакету. Метрики разных протоколов нельзя просто считать одной общей шкалой расстояния.']],[task('Динамический протокол отменяет необходимость настройки?',['Да','Нет'],1,'Нужно задать участие сетей, соседей, политику и контроль.'),task('Перестройка после отказа называется как?',['Сходимость','Трансляция NAT'],0,'Устройства обновляют знания и выбирают новые пути.')]],
['OSPF: общая карта связей',[
['Картина внутри области','OSPF относится к протоколам состояния каналов. Устройства обмениваются описаниями топологии и рассчитывают пути. В рамках области они стремятся иметь согласованную базу состояния каналов. Это отличается от простого совета соседа «иди туда» без представления о связях.'],
['Что мешает соседству','На общей линии должны согласовываться важные параметры, включая область и настройки протокола. Проблемы адресации, фильтрации служебных сообщений и несовместимые параметры могут помешать обмену. Не следует начинать с изменения стоимости, если устройства ещё не стали соседями.'],
['Как читать результат','Посмотрите список соседей, интерфейсы OSPF и установленные маршруты. Наличие соседа не гарантирует анонс нужной подсети. Проверьте, включена ли она в распространение и нет ли фильтра или другой причины выбора пути. Стоимость OSPF определяет предпочтение путей внутри его расчёта.']],[task('OSPF-соседство не поднялось. Что сначала?', ['Проверить линию и согласованные параметры','Поменять цену маршрута наугад'],0,'Расчёт пути не исправит отсутствие обмена соседей.'),task('Сосед есть. Все подсети обязательно уже объявлены?',['Да','Нет'],1,'Анонс нужных сетей проверяется отдельно.')]],
['EIGRP и обмен между протоколами',[
['Другой способ расчёта','EIGRP использует собственные правила выбора путей и проверки допустимого резерва. По умолчанию его метрика опирается на параметры полосы и задержки. Разобрать состояние соседей и топологическую таблицу полезнее, чем запомнить только число в строке маршрута.'],
['Граница двух доменов','Если часть сети использует OSPF, а другая EIGRP, сведения не переходят между ними автоматически. Redistribution переносит выбранные маршруты между протоколами. Нужны фильтры, метрики и защита от возвращения маршрута туда, откуда он пришёл.'],
['Не распространяем всё подряд','Начните с перечня сетей, которыми действительно нужно обменяться. Проверьте основной путь, резерв и поведение при отказе. Бесконтрольный перенос всех записей в обе стороны может создать неожиданные пути и петли. Для небольшого стыка иногда проще использовать ограниченные статические записи.']],[task('OSPF и EIGRP автоматически обмениваются всеми маршрутами?',['Да','Нет'],1,'Нужна осознанная настройка обмена или другой способ связности.'),task('При redistribution важны фильтры?',['Да, чтобы контролировать распространение','Нет, лучше передавать всё'],0,'Нужно ограничить маршруты и предотвратить нежелательную обратную передачу.')]]]);
volume('7','VPN','https://linkmeup.ru/blog/1197/',[
['Туннель и шифрование',[
['Пакет внутри пакета','Туннель переносит одни пакеты внутри других. Внешний адрес помогает пройти по транспортной сети, внутренний относится к соединяемым площадкам. Сам факт упаковки не означает защиты содержимого. Обычный GRE-туннель, например, не даёт шифрования сам по себе.'],
['Что делает IPsec','IPsec может обеспечивать конфиденциальность, целостность и проверку подлинности в зависимости от режима и настроек. Стороны должны согласовать параметры и доверять используемым ключам или сертификатам. Надпись «VPN» без этих подробностей не говорит, насколько защищена связь.'],
['Две независимые задачи','Сначала транспортная сеть должна доставлять внешние пакеты между концами. Затем туннель должен переносить нужный внутренний трафик. Если внешний адрес недоступен, неверно ждать, что один внутренний маршрут всё исправит. Диагностируют транспорт и внутреннюю связность отдельно.']],[task('GRE сам по себе шифрует данные?',['Да','Нет'],1,'GRE инкапсулирует трафик, но не обеспечивает шифрование.'),task('Для туннеля нужны достижимые внешние концы?',['Да','Нет'],0,'Транспорт должен доставлять оболочку туннеля.')]],
['Соединяем площадки',[
['Сети не должны конфликтовать','У двух офисов могут случайно совпасть частные подсети. Простой маршрут через VPN тогда неоднозначен: устройство считает адрес локальным. Для проекта лучше заранее выделить непересекающиеся диапазоны или отдельно продумать преобразование адресов. VPN не отменяет IP-планирование.'],
['Маршрут и разрешение','Внутренние подсети должны направляться в туннель, а фильтры — разрешать нужные службы. При использовании IPsec policy-based селекторы трафика на сторонах также должны соответствовать сценарию. Route-based варианты используют туннельный интерфейс, но и там требуется корректная маршрутизация.'],
['Много филиалов','Для большого числа площадок применяют разные архитектуры: через центральный узел или с прямыми связями между филиалами. DMVPN — один из вариантов динамической многоточечной связи. Выбор зависит от платформ, требований и масштаба; универсального лучшего VPN для любой задачи нет.']],[task('Оба офиса используют 192.168.1.0/24. Это нужно учитывать?',['Да, подсети конфликтуют','Нет, VPN всё исправит'],0,'Адрес может считаться локальным вместо удалённого.'),task('Туннель поднят. Разрешения и маршруты больше не нужны?',['Нужны','Не нужны'],0,'Рабочий туннель ещё не гарантирует доступ к нужной службе.')]],
['MTU и поиск неисправности',[
['Оболочка тоже занимает место','Дополнительные заголовки увеличивают размер передаваемого пакета. Если путь не вмещает его, возможны фрагментация или отказ доставки. Поэтому маленький ping иногда проходит, а большие страницы зависают. MTU нужно рассматривать по всему пути, а не только на компьютере.'],
['Проверка по слоям','Проверяют внешнюю доступность, согласование защитных параметров, счётчики шифрования и расшифрования, внутренние маршруты и фильтры. Если трафик зашифрован на одном конце, но не принят другим, зона поиска отличается от случая, когда пакет вообще не попадает в туннель.'],
['NAT между концами','Промежуточный NAT может изменить условия прохождения VPN. NAT Traversal помогает переносить IPsec в таких сценариях, если стороны и правила его поддерживают. Изменение MTU или MSS делают на основании измерений и понимания протокола, а не одним случайным значением для всех соединений.']],[task('Маленькие пакеты проходят, большие зависают. Что стоит проверить?',['MTU и доставку служебных сообщений','Только имя устройства'],0,'Инкапсуляция уменьшает доступный размер внутреннего пакета.'),task('Для диагностики полезны счётчики шифрования на обеих сторонах?',['Да','Нет'],0,'Они показывают, на каком направлении движется защищённый трафик.')]]]);
volume('1','Подключение к оборудованию','https://linkmeup.ru/blog/1189/',[
['Консоль и удалённый доступ',[
['Как попасть внутрь','Управляемое устройство имеет собственную программу. Мы обращаемся к ней через веб-страницу или терминал. Терминал — окно, в котором команды вводят текстом. Консольное подключение идёт через специальный порт устройства; обычный сетевой кабель не всегда может заменить консольный. Подходящий кабель и параметры подключения зависят от модели.'],
['Когда IP ещё нет','Новому устройству иногда ещё не назначен адрес управления. Тогда подключиться по сети не получится: сначала используют консоль или предусмотренный производителем способ первичной настройки. Для последующего удалённого терминала выбирают SSH: он защищает сеанс шифрованием. Telnet передаёт содержимое без такой защиты.'],
['Перед первой командой','Проверьте имя устройства в приглашении, адрес назначения и свои полномочия. Сохраните рабочую конфигурацию и убедитесь, что есть способ восстановить доступ. В этой Академии команды разбираются как учебные примеры: текст задания не выполняется на устройствах вашей сети.']],[task('У устройства ещё нет IP управления. Какой способ часто помогает начать?', ['SSH по несуществующему адресу','Подходящая консоль','Смена DNS'],1,'Консоль обычно позволяет настроить устройство до появления сетевого доступа.'),task('Что выбрать для защищённого удалённого терминала?',['Telnet','SSH'],1,'SSH шифрует соединение. Одного пароля для защиты Telnet недостаточно.')]],
['Режимы командной строки',[
['Приглашение подсказывает контекст','В классическом Cisco IOS строка Router> означает пользовательский режим. После enable можно попасть в привилегированный режим Router#. Команда configure terminal переводит в глобальную настройку Router(config)#. Это разные контексты: одна и та же команда доступна не везде. Другие производители используют свои приглашения.'],
['Сначала смотрим','Команды show помогают узнать состояние и текущие настройки. Например, show running-config показывает действующую конфигурацию, а show ip interface brief — краткую сводку интерфейсов. Сначала найдите проблему в выводе, затем выбирайте изменение. Устройство может скрывать часть информации в зависимости от прав пользователя.'],
['Помощь вместо угадывания','Знак вопроса и дополнение клавишей Tab помогают найти синтаксис. Сообщение ambiguous означает, что сокращение подходит сразу к нескольким командам. Не копируйте длинный набор строк, не понимая текущего режима. После изменения проверяют результат: отсутствие сообщения об ошибке ещё не доказывает, что связь работает.']],[task('В классическом IOS вы видите Router(config)#. Где вы?',['В глобальной настройке','В обычном пользовательском режиме'],0,'Слово config указывает контекст конфигурации.'),task('Как начать диагностику интерфейсов?',['Сразу удалить настройки','Посмотреть состояние через show'],1,'Наблюдение помогает выбрать нужное изменение и избежать случайных действий.')]],
['Сохранение и восстановление',[
['Работает сейчас и после запуска','Running-config — действующая конфигурация. Startup-config — сохранённая конфигурация, которую устройство обычно использует при загрузке. На классическом IOS копирование running-config в startup-config сохраняет изменения. Если не сохранить, после перезагрузки возможен возврат старых настроек. Поведение других систем уточняют отдельно.'],
['Проверка перед сохранением','Убедитесь, что доступ работает с разрешённого компьютера, нужные интерфейсы подняты, а старые пользователи не потеряли связь. Только после проверки сохраняйте окончательный результат. Перезапуск рабочего устройства влияет на людей, поэтому его не используют как случайную проверку каждой настройки.'],
['Если пароль потерян','Восстановление доступа зависит от модели, версии и политики безопасности. Оно может потребовать физического доступа и остановки работы. Нужны разрешение владельца, документация производителя и резервная копия. Не существует одной безопасной последовательности сброса для всех устройств; заводской сброс может удалить конфигурацию.']],[task('Running-config изменили, но не сохранили. Что может случиться после перезагрузки?',['Изменения могут потеряться','Все настройки всегда сохраняются автоматически'],0,'На классическом IOS действующая и загрузочная конфигурации разделены.'),task('Когда сохранять окончательную конфигурацию?',['После проверки результата','До проверки любой ценой'],0,'Сначала подтверждают, что изменение решило задачу и сохранило доступ.')]]]);
volume('2','Коммутация','https://linkmeup.ru/blog/1190/',[
['Как коммутатор узнаёт получателя',[
['Кадр и MAC','В Ethernet данные передаются кадрами. В кадре есть MAC отправителя и получателя. Коммутатор запоминает MAC отправителя и порт, на котором получил кадр. Так он постепенно строит таблицу адресов. Таблица обычно учитывает VLAN: одинаковый физический коммутатор может обслуживать несколько отдельных сегментов.'],
['Известный и неизвестный адрес','Если порт получателя уже известен, кадр направляется туда. Если MAC назначения неизвестен, кадр распространяется по подходящим портам этого VLAN, кроме входного. Это не отправка во все сети компании. Когда ответ придёт обратно, коммутатор сможет узнать адрес второй стороны.'],
['Проверяем по таблице','Если компьютер не виден, сверяют порт, VLAN и изученные MAC. Отсутствующая запись может означать, что устройство ещё ничего не отправило, выключено или подключено не туда. Таблица не является вечным каталогом: динамические записи стареют и могут изменяться при перестановке кабеля.']],[task('По какому полю коммутатор обучается MAC-адресам?',['По адресу отправителя','По имени сайта'],0,'Он связывает MAC источника с входным портом.'),task('Неизвестный MAC назначения распространяется куда?',['В подходящие порты того же VLAN','Во все VLAN без ограничений'],0,'Распространение ограничено сегментом VLAN и состояниями портов.')]],
['Access, trunk и тег',[
['Порт для конечного устройства','Access-порт в обычном учебном случае относится к одному VLAN. Компьютер посылает обычные Ethernet-кадры без необходимости самостоятельно выбирать VLAN. Коммутатор относит входящий трафик к назначенной порту группе. На практике бывают дополнительные режимы, например отдельный голосовой VLAN.'],
['Линия между коммутаторами','Trunk позволяет переносить несколько VLAN по одной линии. Тег IEEE 802.1Q помогает различать их кадры. Разрешённый список VLAN и обработка нетегированных кадров должны быть согласованы на концах. Если VLAN 20 разрешён только с одной стороны, нужная связь может не работать.'],
['Не путайте линии и сегменты','Добавление кабеля не создаёт новый VLAN автоматически. Создание VLAN не прокладывает кабель. Для рабочего подключения нужны физическая линия, согласованный режим порта и наличие нужной группы на пути. Поэтому проверяют и L1-схему, и логический план.']],[task('По одной линии нужно перенести VLAN 10 и 20. Что подходит?',['Access только VLAN 10','Trunk с разрешёнными VLAN 10 и 20'],1,'Trunk разделяет кадры нескольких VLAN на одном соединении.'),task('VLAN разрешён на одном конце trunk и запрещён на другом. Всё согласовано?',['Да','Нет'],1,'Нужный VLAN должен проходить по всей линии.')]],
['Практикум: связь в одном VLAN',[
['Одинаковая группа — первый шаг','Два компьютера подключены к разным коммутаторам. Оба должны находиться в VLAN 10. На их портах планируется access VLAN 10, а на межкоммутаторной линии — перенос VLAN 10. Затем проверяют IP-адреса: для прямого IP-обмена компьютеры должны правильно определять друг друга как соседей.'],
['Порядок диагностики','Проверяем кабель и состояние порта, затем назначенный VLAN, разрешённый VLAN на trunk и MAC-таблицы. Если L2-связность есть, проверяем адреса, маску и настройки конечных устройств. Локальный межсетевой экран тоже может запретить ответ на ping. Один неуспешный ping не указывает точную причину.'],
['Что записать в ответе','Хорошее решение содержит оба access-порта, межкоммутаторную линию и ожидаемые адреса. Если исправили только один порт, проверьте весь путь снова. Следующий том объясняет обмен между разными IP-подсетями: обычная коммутация сама по себе такую задачу не решает.']],[task('ПК на SW1 и SW2 принадлежат VLAN 10, но trunk его не переносит. Где исправление?',['Разрешить VLAN 10 на нужной линии с обеих сторон','Изменить обои компьютеров'],0,'Путь VLAN должен быть непрерывным.'),task('Всегда ли неудачный ping означает обрыв кабеля?',['Да','Нет, причин несколько'],1,'Нужна последовательная диагностика L1, L2, L3 и конечного устройства.')]]]);
volume('3','Статическая маршрутизация','https://linkmeup.ru/blog/1191/',[
['Когда нужен шлюз',[
['Своя или другая подсеть','Компьютер использует адрес и префикс, чтобы понять, находится ли получатель в его локальной подсети. Для локального соседа обычно нужен его MAC. Для удалённого адреса пакет передают доступному шлюзу. При этом IP назначения остаётся адресом удалённого получателя, а MAC назначения кадра принадлежит следующему узлу.'],
['ARP узнаёт локальный MAC','В IPv4 ARP связывает адрес соседа с его MAC на локальном сегменте. Компьютер не ищет через ARP MAC каждого сервера в интернете. Если сервер удалённый, компьютер обычно узнаёт MAC своего шлюза. Каждый маршрутизатор по пути дальше решает, куда передавать пакет.'],
['Между VLAN','Чтобы VLAN 10 и VLAN 20 обменивались IP-трафиком, планируют L3-интерфейсы и маршрутизацию. Это может делать маршрутизатор или L3-коммутатор. Разрешать обмен целиком необязательно: правила доступа определяют, какие взаимодействия нужны людям.']],[task('Удалённый сервер в другой подсети. Чей MAC обычно нужен компьютеру для первого кадра?',['MAC шлюза','MAC далёкого сервера'],0,'На локальном участке следующим узлом является шлюз.'),task('Меняется ли IP назначения на адрес шлюза при обычной отправке без NAT?',['Да','Нет'],1,'Адрес шлюза определяет следующий шаг, а IP назначения остаётся конечным.')]],
['Читаем таблицу маршрутизации',[
['Сеть и следующий шаг','Маршрут сообщает, для какого префикса и куда передавать пакет. Например: сеть 10.20.0.0/16 через соседний маршрутизатор 192.0.2.2. Следующий узел должен быть достижим. Запись не создаёт физическую связь и не заменяет корректный адрес интерфейса.'],
['Самое точное совпадение','Если назначению подходят несколько установленных маршрутов, выбирается наиболее длинный префикс. Для 10.20.5.8 маршрут 10.20.5.0/24 точнее, чем 10.20.0.0/16. Маршрут по умолчанию 0.0.0.0/0 подходит, когда нет более точного пути. Он не имеет приоритета над всеми маршрутами.'],
['Ответ тоже должен вернуться','Запрос может дойти до сервера, но ответ потеряться из-за отсутствия обратного маршрута. Поэтому проверяют таблицы по обоим направлениям и правила фильтрации. Наличие маршрута к серверу только на первом роутере ещё не доказывает полноценную связность.']],[task('Для 10.20.5.8 подходят /16 и /24. Какой установленный маршрут выбирается?',['/16','/24'],1,'Выбирается самое длинное совпадение префикса.'),task('Запрос дошёл, ответ не возвращается. Что проверить?',['Обратный маршрут и фильтры','Только цвет кабеля'],0,'Связь двусторонняя, обратное направление тоже требует маршрутизации.')]],
['Практикум: два офиса',[
['Исходная схема','В офисе A сеть 10.10.0.0/24, в офисе B — 10.20.0.0/24. Роутеры соединены отдельной линией. На A задают маршрут к сети B через соседа на линии. На B задают обратный маршрут к сети A. Адрес следующего узла берут с общей линии, а не из недостижимой удалённой сети.'],
['Как проверить','Сначала проверяют адреса и доступность соседних интерфейсов. Потом проверяют таблицы маршрутов и обмен между конечными компьютерами. Traceroute помогает увидеть отвечающие промежуточные узлы, но отсутствие ответа одного узла не всегда означает, что он не пересылает данные: служебные ответы могут фильтроваться.'],
['Ограничения ручных маршрутов','Для двух небольших площадок статические записи понятны. При росте сети приходится следить за большим числом путей и отказов. Обычный статический маршрут не гарантирует проверку удалённого сервиса. Позже разберём динамические протоколы и отдельные механизмы контроля доступности.']],[task('На A настроили путь к B. Достаточно для ответа?',['Всегда да','Нет, B тоже нужен путь обратно'],1,'У обратного пакета своя проверка таблицы маршрутов.'),task('Адрес next hop обычно относится к чему?',['К достижимому следующему маршрутизатору','К любому случайному компьютеру'],0,'Пакет нужно передать реально достижимому соседу или разрешимому следующему узлу.')]]]);
